"""Generate firmware name/ordinal maps from the SDK's Symbian import proxies."""
import argparse
import hashlib
from pathlib import Path
import struct


def exports(path):
    data = path.read_bytes()
    if data[:7] != b'\x7fELF\x01\x01\x01' or struct.unpack_from('<H', data, 18)[0] != 40:
        raise ValueError('Expected a little-endian ELF32 ARM import proxy')
    table = struct.unpack_from('<I', data, 32)[0]
    stride, count = struct.unpack_from('<HH', data, 46)
    sections = [struct.unpack_from('<10I', data, table + i * stride) for i in range(count)]
    dynamic = next(section for section in sections if section[1] == 11)
    strings = sections[dynamic[6]]
    names = data[strings[4]:strings[4] + strings[5]]
    result = []
    for pos in range(dynamic[4], dynamic[4] + dynamic[5], dynamic[9]):
        name, value, size, info, _, section_index = struct.unpack_from('<IIIBBH', data, pos)
        if info != 0x12:  # STB_GLOBAL, STT_FUNC
            continue
        section = sections[section_index]
        if size != 4 or not section[3] <= value < section[3] + section[5]:
            raise ValueError('Expected one ordinal word per proxy function')
        ordinal = struct.unpack_from('<I', data, section[4] + value - section[3])[0]
        symbol = names[name:names.index(0, name)].decode('ascii')
        result.append((symbol, ordinal))
    return hashlib.sha256(data).hexdigest(), sorted(result)


parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--sdk', required=True, type=Path)
parser.add_argument('--output', type=Path, default=Path(__file__).with_name('SymbianNativeExports.inc'))
args = parser.parse_args()
lines = ['// Generated by generate_symbian_exports.py from original Symbian import contracts.',
         '// Do not infer ordinals from ELF symbol indexes: each proxy body stores its ordinal.', '']
for dll, table in [('libegl', 'kNativeEGLExports'), ('libglesv2', 'kNativeGLES2Exports')]:
    digest, entries = exports(args.sdk / 'proxies' / dll / (dll + '.dso'))
    lines += ['// ' + dll + '.dso SHA-256: ' + digest,
              'constexpr NativeEntryPoint ' + table + '[] = {']
    lines += ['    {"' + name + '", ' + str(ordinal) + '},' for name, ordinal in entries]
    lines += ['};', '']
args.output.write_text('\n'.join(lines))
